SELECT sod.order_id AS order_id, COALESCE(SUM(sdd.qty), 0) AS shipped_qty FROM sal_order_detail sod JOIN sal_delivery_detail sdd ON sdd.order_detail_id = sod.id JOIN sal_delivery sd ON sd.id = sdd.delivery_id WHERE sod.order_id IN
#{oid}
AND sd.bill_status = 'CHECKED' AND sd.deleted = 0 AND sdd.deleted = 0 AND sod.deleted = 0 GROUP BY sod.order_id
